"""Chile appellation profiles (Decreto 464 zoning + 2018/2025 additions + Secano Interior)."""
import sys
sys.path.insert(0, "/home/claude/winesite/scripts/c11")
from c11_common import app  # noqa: E402

C = "cl"
D464 = "1994 (Decreto 464)"


def area(name, region, sub, text, compl=None, **kw):
    """Commune-based 'Área' DO. compl = Costa / Entre Cordilleras / Andes (art. 5 bis)."""
    s = text
    if compl:
        s += f" Labels may add the complement *{compl}*."
    kw.setdefault("created", D464)
    kw.setdefault("subcat", "Área")
    return app(C, name, "DO", s, region=region, subregion=sub, **kw)


